let posPosterFile=null,posPosterGeneration=0,posPosterBusy=false;
function openPosShare(id,mode='longest'){
 $('posShareMode').value=mode;$('posShareYear').value=lifeToday().slice(0,4);$('posShareYear').max=lifeToday().slice(0,4);$('posShareHide').checked=true;$('posSharePhotos').checked=false;$('posShareName').value='我的';
 $('posShareChoices').innerHTML=posLive().map(p=>`<label class="option-row"><span>${escapeHtml(p.name)}</span><input type="checkbox" value="${p.id}" ${!id||p.id===id?'checked':''}></label>`).join('')||'<p class="import-help">还没有可分享的物品。</p>';open('posShareModal');renderPosPoster();
}
function posPosterButtons(){const unavailable=!posPosterFile||posPosterBusy;$('posShareSave').disabled=$('posShareSend').disabled=unavailable;$('posShareSend').hidden=!onAndroid()&&!(navigator.share&&navigator.canShare);}
async function renderPosPoster(){
 const gen=++posPosterGeneration;posPosterFile=null;posPosterButtons();$('posShareCanvas').hidden=true;
 try{const mode=$('posShareMode').value,year=Number(['longest','achievement'].includes(mode)?lifeToday().slice(0,4):$('posShareYear').value);$('posShareYear').disabled=['longest','achievement'].includes(mode);if(!Number.isInteger(year)||year<1970||year>Number(lifeToday().slice(0,4)))throw new Error('请选择有效的回顾年份');const ids=[...$('posShareChoices').querySelectorAll('input:checked')].map(i=>i.value);let review=JianjiPossessions.review(data.possessions,year,mode,lifeToday(),ids);
   if(mode==='achievement'){review.items=review.items.filter(p=>JianjiPossessions.goal(p)?.reached);review.count=review.items.length;}
   if(!review.items.length)throw new Error(mode==='achievement'?'勾选的物品还没有达成日均小目标':'当前选择范围内没有物品');
   const options={mode,year,theme:$('posShareTheme').value,name:$('posShareName').value.trim()||'我的',hide:$('posShareHide').checked,photos:$('posSharePhotos').checked},images=new Map();
   if(options.photos)for(const p of review.items.slice(0,6)){if(p.cover!=='photo'||!p.photoId)continue;const blob=await photoStore('get',p.photoId);if(blob){try{images.set(p.id,await createImageBitmap(blob));}catch{ /* Use its icon when an image cannot be decoded. */ }}}
   try{if(gen!==posPosterGeneration||!$('appLockOverlay').hidden)return;drawPosPoster($('posShareCanvas'),review,options,images);}finally{for(const img of images.values())img.close();}
   const blob=await new Promise(r=>$('posShareCanvas').toBlob(r,'image/png'));if(gen!==posPosterGeneration)return;if(!blob)throw new Error('图片生成失败');posPosterFile=new File([blob],`简记-物品${mode==='achievement'?'成就':'回顾'}-${year}.png`,{type:'image/png'});$('posShareCanvas').hidden=false;$('posShareStatus').textContent=`${review.count} 件已选择物品${review.count>6?' · 卡片展示前 6 件':''}${options.hide?' · 金额已隐藏':''} · ${options.photos?'使用所选封面照片':'使用内置图标'}`;$('posShareCanvas').setAttribute('aria-label',`物品回顾卡，${review.count} 件物品${options.hide?'，具体金额已隐藏':''}，不包含备注或凭证。`);
 }catch(e){if(gen===posPosterGeneration)$('posShareStatus').textContent=e.message||'卡片生成失败';}finally{if(gen===posPosterGeneration)posPosterButtons();}
}
function drawPosPoster(canvas,r,o,images){
 const list=r.items.slice(0,6),t=reportThemes[o.theme]||reportThemes.purple;canvas.width=1080;canvas.height=1120+list.length*170;const c=canvas.getContext('2d'),font='"Microsoft YaHei","PingFang SC",sans-serif';
 const text=(s,x,y,size=27,color=t.ink,weight=400)=>{c.font=`${weight} ${size}px ${font}`;c.fillStyle=color;c.fillText(s,x,y);};const fit=(s,x,y,w,size=30,color=t.ink,weight=400)=>{c.font=`${weight} ${size}px ${font}`;let v=String(s);while(c.measureText(v).width>w&&size>19){size-=2;c.font=`${weight} ${size}px ${font}`;}while(c.measureText(v).width>w&&v.length)v=v.slice(0,-1);text(v,x,y,size,color,weight);};const card=(x,y,w,h,color=t.card)=>{c.beginPath();c.roundRect(x,y,w,h,28);c.fillStyle=color;c.fill();};const amount=n=>o.hide?'•••':money(n).replace(' ','');
 c.fillStyle=t.paper;c.fillRect(0,0,canvas.width,canvas.height);text('简记 · 归物本',66,84,27,t.accent,600);text('让物品的故事，也被记住',665,84,23,t.muted);c.strokeStyle=t.accent;c.lineWidth=3;c.beginPath();c.arc(942,184,38,0,Math.PI*2);c.stroke();text('✦',898,265,48,t.accent);
 const titles={longest:'陪伴最久的物品',new:'今年添了什么',year:'物品年度回顾',achievement:'日均成本小成就'};fit(o.name+titles[o.mode],66,203,800,64,t.ink,700);text(['new','year'].includes(o.mode)?`${o.year} 年 · 截至 ${r.through.replaceAll('-','.')}`:`记录于 ${lifeToday().replaceAll('-','.')}`,69,263,25,t.muted);
 card(64,312,952,180,t.soft);text(o.mode==='achievement'?'陪伴，让小目标慢慢实现':'喜欢的东西，值得陪伴得更久',96,366,29,t.accent,600);
 const a=o.mode==='year'?`${r.heldDays} 天`:`${r.count} 件`,b=o.mode==='year'?'物品陪伴天数累计':'选择的物品';text(a,96,437,48,t.ink,700);text(b,405,437,24,t.accent);text(o.mode==='year'?`其中 ${r.newCount} 件于本年购入`:'不急着换新，慢慢看见它的价值',96,474,21,t.muted);
 card(64,518,952,148);text(o.mode==='year'?'本年购入金额':'所选物品购入金额',96,561,23,t.muted);fit(amount((o.mode==='year'?r.newTotal:r.items.reduce((s,p)=>s+p.priceCents,0))/100),96,622,780,46,t.ink,600);
 let y=696;for(const p of list){const m=JianjiPossessions.metrics(p,['longest','achievement'].includes(o.mode)?lifeToday():r.through);card(64,y,952,145);const x=91,iy=y+22,w=101,img=images.get(p.id);c.save();c.beginPath();c.roundRect(x,iy,w,w,22);c.clip();c.fillStyle=t.soft;c.fillRect(x,iy,w,w);if(img){const scale=Math.max(w/img.width,w/img.height);c.drawImage(img,x+(w-img.width*scale)/2,iy+(w-img.height*scale)/2,img.width*scale,img.height*scale);}else{const icon=JianjiPossessions.icons.find(i=>i[0]===p.icon)||JianjiPossessions.icons.at(-1);c.translate(x+20,iy+20);c.scale(2.5,2.5);c.strokeStyle=t.accent;c.fillStyle=t.card;c.lineWidth=1.3;c.lineJoin='round';c.lineCap='round';const path=new Path2D(icon[3]);c.fill(path);c.stroke(path);}c.restore();
   fit(p.name,225,y+52,730,30,t.ink,600);text(`${m.age} · ${m.days} 天陪伴`,225,y+92,24,t.muted);text(o.mode==='achievement'?'日均小目标已达成':o.mode==='year'?'本年陪伴':o.mode==='new'?'本年添置':JianjiPossessions.states[p.state],225,y+124,22,t.accent);fit(o.hide?'金额已隐藏':`日均净成本 ${amount(m.daily)}`,664,y+124,302,23,t.accent);y+=170;}
 card(64,y+4,952,190,t.soft);text(o.mode==='achievement'?'一份小小的成就，也是生活的脚印':'拥有的每一件物品，都有自己的故事',96,y+64,29,t.accent,600);text(o.hide?'具体金额已隐藏，分享的是陪伴的时光。':'日均净成本按购入、追加费用与回收金额计算。',96,y+111,24,t.muted);text(r.count>6?`汇总含 ${r.count} 件物品，图片展示其中 6 件。`:'仅反映所选物品记录，不代表当前市场价值。',96,y+153,22,t.muted);text('简记 · 每一天，都清清楚楚',66,canvas.height-61,25,t.accent,600);
}
async function exportPosPoster(share){if(!posPosterFile||posPosterBusy||!$('appLockOverlay').hidden)return;posPosterBusy=true;posPosterButtons();try{const file=posPosterFile;if(onAndroid()){const result=await window.Capacitor.nativePromise('ReportExport',share?'share':'save',{name:file.name,contents:$('posShareCanvas').toDataURL('image/png').split(',')[1]});toast(result?.cancelled?'已取消':share?'已返回简记':'物品卡片已保存');}else if(share){if(!navigator.canShare?.({files:[file]}))throw new Error('浏览器不支持图片分享，请先保存');await navigator.share({files:[file],title:'简记 · 物品回顾'});}else{const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('图片已下载');}}catch(e){if(e.name!=='AbortError')toast(e.message||'导出未完成');}finally{posPosterBusy=false;posPosterButtons();}}
function setupPosShare(){for(const id of ['posShareMode','posShareYear','posShareName','posShareTheme','posShareHide','posSharePhotos'])$(id).oninput=renderPosPoster;$('posShareChoices').onchange=renderPosPoster;$('posShareSave').onclick=()=>exportPosPoster(false);$('posShareSend').onclick=()=>exportPosPoster(true);}
